      if(!fly){if(d.press){if(ps.t<1.0){tx=d.x;ty=d.y;vm=0.5;ac=4;}else{tx=a.x+0.6;ty=a.y;vm=L.press;ac=5;}}else{const m=ps.mates.reduce((q,mm)=>Math.hypot(mm.x-d.x,mm.y-d.y)<Math.hypot(q.x-d.x,q.y-d.y)?mm:q,ps.mates[0]);tx=d.hx+(m.x-d.hx)*0.15;ty=d.hy+((a.y+m.y)/2-d.hy)*0.35;vm=2.5;ac=5;}}
