    if(lv>=1){const pts=this.passSim(T,2.5,0.05),lane=ps.laneNow;c.strokeStyle=lane&&lane.mg<0?'rgba(255,107,115,0.85)':'rgba(95,227,161,0.85)';c.lineWidth=2.2;c.setLineDash([6,5]);c.beginPath();let f=true;pts.forEach(q=>{const pp=this.P(q.x,q.y,q.z+0.05);if(!pp)return;f?c.moveTo(pp.x,pp.y):c.lineTo(pp.x,pp.y);f=false;});c.stroke();c.setLineDash([]);}
    else if(pb&&pt){c.setLineDash([5,6]);c.strokeStyle='rgba(232,238,249,0.5)';c.lineWidth=1.5;line(c,pb.x,pb.y,pt.x,pt.y);c.setLineDash([]);}
