  P(x,y,z){const fl=this.flipCam,d=fl?(this.camX||46)-x:x-(this.att.x-(this.camBack||DR.BACK));if(d<0.35)return null;const s=DR.F/d;return{x:W/2+(fl?this.camY-y:y-this.camY)*s,y:DR.CY+((this.camH||DR.CH)-z)*s,s,d};},
  dep(x){return this.flipCam?(this.camX||46)-x:x-(this.att.x-(this.camBack||DR.BACK));},
  sd(v){return this.flipCam?-v:v;},
